func (db *DB) RaiseDecision(ctx context.Context, request DecisionRequest) (Decision, error) {
	if request.ProjectID < 1 || request.TaskID < 1 || strings.TrimSpace(request.Origin) == "" || strings.TrimSpace(request.Question) == "" || len(request.Options) < 1 {
		return Decision{}, fmt.Errorf("decision requires a Project, Task, origin, question and at least one option")
	}
	switch request.Kind {
	case "merge_ready", "recovery", "worker_exited", "review", "review_cap", "worker_question", "orphan", "pr_closed", "dependency", "teardown_dependants", "quota", "budget", "review_dispute":
	default:
		return Decision{}, fmt.Errorf("invalid Decision kind %q", request.Kind)
	}
	if len(request.Evidence) > 64*1024 {
		return Decision{}, fmt.Errorf("decision evidence exceeds the 64 KiB limit")
	}
	if request.Kind == "review_dispute" && (len(request.Evidence) == 0 || !slices.Equal(request.Options, []string{"withdraw", "keep"})) {
		return Decision{}, fmt.Errorf("review dispute Decisions require evidence and the withdraw, keep options")
	}
	if request.Kind != "review_dispute" && len(request.Evidence) > 0 {
		return Decision{}, fmt.Errorf("evidence is supported only for review dispute Decisions")
	}
	evidenceDigest := ""
	if request.Evidence == nil {
		request.Evidence = []byte{}
	}
	if len(request.Evidence) > 0 {
		digest := sha256.Sum256(request.Evidence)
		evidenceDigest = hex.EncodeToString(digest[:])
	}
	seen := map[string]bool{}
	for _, option := range request.Options {
		if strings.TrimSpace(option) != option || option == "" || seen[option] {
			return Decision{}, fmt.Errorf("decision options must be distinct and non-empty")
		}
		seen[option] = true
	}
	options, err := json.Marshal(request.Options)
	if err != nil {
		return Decision{}, err
	}
	tx, err := db.beginTxWithRetry(ctx)
	if err != nil {
		return Decision{}, err
	}
	defer tx.Rollback()
	if original, err := decisionRow(tx.QueryRowContext(ctx, decisionSelect+` WHERE project_id=? AND origin=?`, request.ProjectID, request.Origin)); err == nil {
		// A dependency question names the prerequisite's current state, which
		// may move (failed, then torn-down) under the same origin.
		if original.Kind == "review_cap" && request.Kind == "review_cap" && original.TaskID == request.TaskID && original.Question == request.Question && original.AnsweredAt == 0 && original.ObsoleteAt == 0 {
			if !slices.Equal(original.Options, request.Options) {
				if _, err := tx.ExecContext(ctx, `UPDATE decisions SET options_json=? WHERE id=?`, string(options), original.ID); err != nil {
					return Decision{}, err
				}
				if err := tx.Commit(); err != nil {
					return Decision{}, err
				}
				if err := db.PersistProject(ctx, request.ProjectID); err != nil {
					return Decision{}, err
				}
				original.Options = request.Options
			}
			return original, nil
		}
		if original.Kind == "dependency" && request.Kind == "dependency" && original.TaskID == request.TaskID && original.Question != request.Question && slices.Equal(original.Options, request.Options) {
			if original.AnsweredAt != 0 || original.ObsoleteAt != 0 {
				return original, nil
			}
			if _, err := tx.ExecContext(ctx, `UPDATE decisions SET question=? WHERE id=?`, request.Question, original.ID); err != nil {
				return Decision{}, err
			}
			if err := tx.Commit(); err != nil {
				return Decision{}, err
			}
			if err := db.PersistProject(ctx, request.ProjectID); err != nil {
				return Decision{}, err
			}
			original.Question = request.Question
			return original, nil
		}
		if original.TaskID != request.TaskID || original.Kind != request.Kind || original.Question != request.Question || !slices.Equal(original.Options, request.Options) || !slices.Equal(original.Evidence, request.Evidence) {
			return Decision{}, fmt.Errorf("decision origin %q already belongs to another question", request.Origin)
		}
		return original, nil
	} else if !errors.Is(err, ErrNotFound) {
		return Decision{}, err
	}
	if request.Kind == "recovery" {
		var existingID int64
		err := tx.QueryRowContext(ctx, `SELECT id FROM decisions WHERE task_id=? AND kind='recovery' AND answered_at=0 AND obsolete_at=0`, request.TaskID).Scan(&existingID)
		if err == nil {
			return decisionRow(tx.QueryRowContext(ctx, decisionSelect+` WHERE id=?`, existingID))
		}
		if !errors.Is(err, ErrNotFound) {
			return Decision{}, err
		}
	}
	result, err := tx.ExecContext(ctx, `INSERT INTO decisions(project_id,task_id,origin,question,options_json,created_at,kind,task_launches)
		SELECT ?,?,?,?,?,?,?,launches FROM tasks WHERE id=? AND project_id=?
		ON CONFLICT(project_id,origin) DO NOTHING`, request.ProjectID, request.TaskID, request.Origin, request.Question, string(options), time.Now().UnixMilli(), request.Kind, request.TaskID, request.ProjectID)
	if err != nil {
		return Decision{}, err
	}
	count, err := result.RowsAffected()
	if err != nil {
		return Decision{}, err
	}
	decision, err := decisionRow(tx.QueryRowContext(ctx, decisionSelect+` WHERE project_id=? AND origin=?`, request.ProjectID, request.Origin))
	if errors.Is(err, ErrNotFound) {
		return Decision{}, fmt.Errorf("decision Task does not belong to Project")
	}
	if err != nil {
		return Decision{}, err
	}
	if count == 1 && len(request.Evidence) > 0 {
		if _, err := tx.ExecContext(ctx, `INSERT INTO decision_evidence(decision_id,evidence,digest) VALUES(?,?,?)`, decision.ID, request.Evidence, evidenceDigest); err != nil {
			return Decision{}, err
		}
		decision.Evidence, decision.EvidenceDigest = request.Evidence, evidenceDigest
	}
	if count == 0 && (decision.TaskID != request.TaskID || decision.Kind != request.Kind || decision.Question != request.Question || !slices.Equal(request.Options, decision.Options) || !slices.Equal(request.Evidence, decision.Evidence)) {
		return Decision{}, fmt.Errorf("decision origin %q already belongs to another question", request.Origin)
	}
	if err := tx.Commit(); err != nil {
		return Decision{}, err
	}
	if err := db.PersistProject(ctx, request.ProjectID); err != nil {
		return Decision{}, err
	}
	return decision, nil
}

