567: 	result, err := db.ExecContext(ctx, `UPDATE decisions AS d SET obsolete_at=?,obsolete_reason=CASE d.kind
568: 		WHEN 'merge_ready' THEN CASE WHEN EXISTS(SELECT 1 FROM tasks WHERE id=d.task_id AND state NOT IN ('done','merging')) THEN 'Task left merge-ready state' ELSE 'PR is no longer ready to merge' END
569: 		WHEN 'worker_exited' THEN 'Task reopened or Worker launch changed'
570: 		WHEN 'pr_closed' THEN 'Closed PR was reopened, replaced or Task discarded'
571: 		WHEN 'orphan' THEN 'Unrecoverable Orphan resolved during Teardown'
572: 		WHEN 'quota' THEN 'Worker relaunched or Task left its working states'
573: 		WHEN 'budget' THEN 'Budget Decision no longer applies to this Worker launch, Task state or Project day'
574: 		WHEN 'dependency' THEN 'Queued Task or prerequisite state changed'
575: 		ELSE 'Task no longer failed or lost' END
576: 		WHERE d.project_id=? AND d.answered_at=0 AND d.obsolete_at=0 AND d.kind IN ('merge_ready','recovery','worker_exited','pr_closed','orphan','quota','budget','dependency')
577: 		AND EXISTS(SELECT 1 FROM tasks t WHERE t.id=d.task_id AND (`+resolvedDecisionPredicate+`))`, time.Now().UnixMilli(), projectID)
578: 	if err != nil {
579: 		return err
